import {leakPenalty} from './office-time.js?v=18';
import {careerTitle} from './career-paths.js?v=15';
import { TYPES, FACTIONS, LEVELS, EVENTS, PRESSURE, matchup, waveSpec } from './config.js?v=30';
/** Deterministic rules outside the renderer; RNG injected for event selection. */
export class Game {
 constructor(onEvent=()=>{},random=Math.random){this.onEvent=onEvent;this.random=random;this.records={};this.reset(0);}
 emit(type,text,details={}){this.onEvent({type,text,...details});}
 reset(level=0){this.level=level;this.map=LEVELS[level];this.state={money:this.map.budget,lives:20,overtime:0,leaks:0,wave:0,active:false,enemies:[],towers:[],effects:[],spawned:0,spawnTimer:0,faction:'byte',kills:0,ended:false,won:false,time:0,event:null,eventUntil:0,rollback:0};this.feedback=[];this.selectedType=0;this.selectedSlot=-1;this.speed=1;this.paused=false;this.status='招募伙伴，守住今天的下班时间';this.emit('change');}
 get tower(){return this.state.towers.find(t=>t.slot===this.selectedSlot);}
 get event(){return this.state.event||{};}
 aura(t){let bonus=0;for(const peer of this.state.towers){if(peer.slot===t.slot||(peer.branch!=='manager'||peer.type!==0))continue;const a=this.map.slots[t.slot],b=this.map.slots[peer.slot];if(Math.hypot(a[0]-b[0],a[1]-b[1])<(peer.level===4?220:175))bonus=Math.max(bonus,peer.level===4?.28:.18);}return bonus;}
 range(t){return TYPES[t.type].range*(1+.1*t.level)*(this.state.faction==='tencent'?1.18:1)*(this.event.range||1);}
 damage(t){return Math.round(TYPES[t.type].damage*(1+t.level*.72)*(t.branch==='ic'?1.4:t.branch==='manager'?.88:1)*(1+this.aura(t))*(this.event.damage||1)*(t.type===0?(this.event.devDamage||1):t.type===2?(this.event.designDamage||1):1));}
 income(t){return Math.round((18+t.level*14)*(t.branch==='ic'?1.65:1)*(this.event.income||1));}
 upgradeCost(t){return Math.round(TYPES[t.type].cost*[.85,1.25,1.75,2.4][t.level]);}
 chooseType(type){this.selectedType=type;if(this.tower)this.selectedSlot=-1;this.status=`已选择${TYPES[type].name} · 选工位后确认建造`;this.emit('change');}
 chooseFaction(faction){if(this.state.wave||!FACTIONS[faction])return;this.state.faction=faction;this.emit('change');}
 slot(index){if(this.state.ended||!Number.isInteger(index)||!this.map.slots[index])return;this.selectedSlot=index;this.emit('change');}
 build(){const index=this.selectedSlot;if(this.state.ended||!this.map.slots[index]||this.tower)return;const d=TYPES[this.selectedType];if(this.state.money<d.cost)return this.emit('toast',`预算不足，还差 ${d.cost-this.state.money}`);this.state.money-=d.cost;this.state.towers.push({slot:index,type:this.selectedType,level:0,branch:null,cooldown:this.selectedType===4?8:.15,invested:d.cost,committed:this.state.active});this.status=`${d.name}已就位 · 点击伙伴查看晋升`;this.celebrate(this.tower,'入驻成功');this.emit('build');}
 refund(t){return t.committed?Math.floor(t.invested*.7):t.invested;}

 upgrade(branch){const t=this.tower;if(!t||t.level>=4||this.state.ended)return;if(t.level===2&&!['ic','manager'].includes(branch))return this.emit('toast','请选择独立贡献者或管理路线');const cost=this.upgradeCost(t);if(this.state.money<cost)return this.emit('toast',`晋升预算不足，还差 ${cost-this.state.money}`);this.state.money-=cost;t.invested+=cost;if(t.level===2)t.branch=branch;t.level++;this.emit('toast',`${TYPES[t.type].name}晋升 ${FACTIONS[this.state.faction].ranks[t.level]} · ${careerTitle(TYPES[t.type],t)}`);this.celebrate(t,'晋升成功');this.emit('build');}
 celebrate(t,label){const [x,y]=this.map.slots[t.slot];this.feedback.push({x,y,color:TYPES[t.type].color,label,life:1.15,max:1.15});}
 updateFeedback(dt){for(const f of this.feedback)f.life-=Math.min(dt,.05);this.feedback=this.feedback.filter(f=>f.life>0);}

 sell(){const t=this.tower;if(!t||this.state.ended)return;this.state.money+=this.refund(t);this.state.towers=this.state.towers.filter(v=>v!==t);this.selectedSlot=-1;this.emit('change');}
 start(){const s=this.state;if(s.active||s.ended)return;if(!s.towers.some(t=>t.type!==4))return this.emit('toast','先部署至少一位有攻击能力的伙伴');for(const t of s.towers)t.committed=true;s.wave++;s.active=true;s.spawned=0;s.spawnTimer=.3;this.paused=false;if(s.wave>s.eventUntil)s.event=null;if(s.wave%3===0){let choices=EVENTS.filter(e=>e.id!==s.event?.id);s.event=choices[Math.floor(this.random()*choices.length)];s.eventUntil=s.wave+1;s.money+=s.event.grant||0;this.emit('toast',`${s.event.name}：${s.event.desc}`);}this.status=`第 ${s.wave} 波 · ${waveSpec(this.level,s.wave).name}`;this.emit('change');}
 adapt(){const s=this.state;if(s.ended||!s.event||s.event.kind!=='debuff')return;if(s.money<60)return this.emit('toast','适配需要 60 预算');s.money-=60;s.event=null;s.eventUntil=0;this.emit('toast','适配完成，本次负面事件已解除');this.emit('change');}
 rollback(){const s=this.state;if(!s.active||s.ended||s.rollback>0)return;for(const e of s.enemies){e.slow=4;e.slowFactor=.2;}s.rollback=40;this.emit('toast','一键回滚：全场需求减速 80%，持续 4 秒');this.emit('change');}
 spawn(){const s=this.state;let kind=waveSpec(this.level,s.wave).kind;if(kind==='mix')kind=['paper','bug','fast','model'][s.spawned%4];const hp=Math.round(({paper:56,bug:74,fast:43,boss:620,meeting:95,model:105,queen:500,deadline:800}[kind])*(1+(s.wave-1)*.22)*PRESSURE[this.level]);s.enemies.push({x:this.map.route[0][0],y:this.map.route[0][1],segment:0,progress:0,hp,maxHp:hp,speed:{paper:48,bug:62,fast:98,boss:29,meeting:43,model:55,queen:36,deadline:26}[kind],kind,slow:0,slowFactor:.55,mark:0,markBonus:.35,alive:true,phase:this.random()*6});s.spawned++;}
 hit(e,damage,type){if(!e.alive)return;const s=this.state;e.hitFlash=.14;e.hp-=damage*matchup(e.kind,type,e.shieldBreak>0)*(e.mark>0?1+e.markBonus:1);if(e.hp<=0){e.alive=false;s.kills++;const reward=Math.round((['boss','deadline','queen'].includes(e.kind)?100:13)*(s.faction==='ali'?1.25:1)*(this.event.reward||1));s.money+=reward;s.effects.push({x:e.x,y:e.y,life:.6,max:.6,color:'#fff5b2',text:'+'+reward});this.emit('hit');}}
 finish(won){const s=this.state;s.ended=true;s.active=false;s.won=won;this.records[this.level]=Math.max(this.records[this.level]||0,won?this.map.waves:s.wave-1);this.status=won?'下班啦，明天见。':'调整策略，再守一次。';this.emit('end');}
 update(seconds){const s=this.state;if(this.paused||s.ended||!s.active)return;const dt=Math.min(seconds,.05)*this.speed;s.time+=dt;s.rollback=Math.max(0,s.rollback-dt);s.spawnTimer-=dt;const spec=waveSpec(this.level,s.wave);if(s.spawnTimer<=0&&s.spawned<spec.count){this.spawn();s.spawnTimer=['boss','deadline'].includes(spec.kind)?5:Math.max(.5,.98-this.level*.09);}
 for(const e of s.enemies){if(!e.alive)continue;e.hitFlash=Math.max(0,(e.hitFlash||0)-dt);e.shieldBreak=Math.max(0,(e.shieldBreak||0)-dt);e.slow=Math.max(0,e.slow-dt);e.mark=Math.max(0,e.mark-dt);let distance=e.speed*(e.slow>0?e.slowFactor:1)*(this.event.enemySpeed||1)*dt;while(distance>0&&e.alive){const p=this.map.route[e.segment+1];if(!p){e.alive=false;const penalty=leakPenalty(e.kind);s.lives=Math.max(0,s.lives-penalty.lives);s.overtime+=penalty.minutes;s.leaks++;this.feedback.push({x:Math.min(965,e.x),y:Math.max(35,Math.min(545,e.y)),kind:'overtime',color:'#d47145',label:`加班 +${penalty.minutes} 分钟`,life:2,max:2});this.emit('leak',`需求溜进出口 · 加班 +${penalty.minutes} 分钟`,{minutes:penalty.minutes});break;}const dx=p[0]-e.x,dy=p[1]-e.y,len=Math.hypot(dx,dy);if(distance>=len){e.x=p[0];e.y=p[1];e.segment++;distance-=len;}else{e.x+=dx/len*distance;e.y+=dy/len*distance;distance=0;}}e.progress=e.segment+e.x/10000;e.phase+=dt*5;}
 for(const t of s.towers){t.shot=Math.max(0,(t.shot||0)-dt);t.cooldown-=dt;if(t.cooldown>0)continue;const d=TYPES[t.type],[x,y]=this.map.slots[t.slot];if(t.type===4){const gain=this.income(t);s.money+=gain;t.cooldown=8;s.effects.push({x,y:y-30,life:1,max:1,color:'#f3c151',text:'+'+gain});continue;}const targets=s.enemies.filter(e=>e.alive&&Math.hypot(e.x-x,e.y-y)<this.range(t)).sort((a,b)=>b.progress-a.progress);if(!targets.length)continue;t.cooldown=d.rate/(1+t.level*.12)/(s.faction==='byte'?1.12:1)/(this.event.rate||1);for(const target of targets.slice(0,t.type===0&&t.branch==='ic'&&t.level===4?2:1)){t.shot=.12;s.effects.push({slot:t.slot,x,y:y-35,tx:target.x,ty:target.y,life:.42,max:.42,color:d.color,job:t.type,power:t.level});if(t.type===1){target.slow=2+t.level*.3;target.slowFactor=t.branch==='ic'?.35:.55;if(t.branch==='manager'){const radius=t.level===4?95:70;for(const e of s.enemies)if(e.alive&&Math.hypot(e.x-target.x,e.y-target.y)<radius){e.slow=Math.max(e.slow,t.level===4?3:2.5);e.slowFactor=Math.min(e.slowFactor,.55);}};}if(t.type===3){if(target.kind==='model')target.shieldBreak=t.branch==='manager'?(t.level===4?8:6):4;target.mark=t.branch==='manager'?(t.level===4?7:5):3+(t.branch==='ic'?2:0);target.markBonus=t.branch==='ic'?.65:t.branch==='manager'?(t.level===4?.65:.5):.35;}if(t.type===2){const radius=t.branch==='ic'?(t.level===4?110:90):65;s.effects.push({x:target.x,y:target.y,life:.5,max:.5,color:d.color,radius,job:2,blast:true,power:t.level});for(const e of s.enemies)if(e.alive&&Math.hypot(e.x-target.x,e.y-target.y)<radius){if(t.branch==='manager'){e.slowFactor=e.slow>0?Math.min(e.slowFactor,t.level===4?.7:.8):(t.level===4?.7:.8);e.slow=Math.max(e.slow,1.5);}this.hit(e,this.damage(t),t.type);}}else this.hit(target,this.damage(t),t.type);}}
 s.enemies=s.enemies.filter(e=>e.alive);for(const f of s.effects)f.life-=dt;s.effects=s.effects.filter(f=>f.life>0);if(s.lives<=0){this.finish(false);return;}if(s.spawned===spec.count&&!s.enemies.length){s.active=false;let reward=40+s.wave*5;for(const t of s.towers)if(t.type===4&&t.branch==='manager')reward+=t.level===4?70:40;s.money+=reward;s.effects=[];if(s.wave===this.map.waves){this.finish(true);return;}this.status='调整工位，下一波由你决定';this.emit('toast',`第 ${s.wave} 波完成 · 整备预算 +${reward}`);this.emit('change');}
 }
}
